#define GCREG_SHADER_CONFIG_LS_RELATIVE_INDEX_STRIDE_Type                    U02
/* a0/aL strides are register wide. */
#define   GCREG_SHADER_CONFIG_LS_RELATIVE_INDEX_STRIDE_COMPATIBLE            0x0
/* a0/aL strides are based on the instruction type (1, 2, or 4 bytes). */
#define   GCREG_SHADER_CONFIG_LS_RELATIVE_INDEX_STRIDE_ADAPTIVE              0x1
/* a0/aL strides are 1 byte. */
