/* Sub Sample Mask Location */
#define AQ_PIXEL_SHADER_TEMPORARY_REGISTER_CONTROL_SUB_SAMPLE_MASK_LOCATION 31:30
#define AQ_PIXEL_SHADER_TEMPORARY_REGISTER_CONTROL_SUB_SAMPLE_MASK_LOCATION_End 31
#define AQ_PIXEL_SHADER_TEMPORARY_REGISTER_CONTROL_SUB_SAMPLE_MASK_LOCATION_Start 30
#define AQ_PIXEL_SHADER_TEMPORARY_REGISTER_CONTROL_SUB_SAMPLE_MASK_LOCATION_Type U02
/* sub sample Mask is in sub sample depth register. */
#define   AQ_PIXEL_SHADER_TEMPORARY_REGISTER_CONTROL_SUB_SAMPLE_MASK_LOCATION_SUB_Z 0x0
/* sub sample Mask is in Z register. */
#define   AQ_PIXEL_SHADER_TEMPORARY_REGISTER_CONTROL_SUB_SAMPLE_MASK_LOCATION_Z 0x1
/* sub sample Mask is in W register. */
#define   AQ_PIXEL_SHADER_TEMPORARY_REGISTER_CONTROL_SUB_SAMPLE_MASK_LOCATION_W 0x2
/* sub sample Mask is in smask register. */
#define   AQ_PIXEL_SHADER_TEMPORARY_REGISTER_CONTROL_SUB_SAMPLE_MASK_LOCATION_SMASK 0x3

/* Register AQPixelShaderControl **
** ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ */
#define AQPixelShaderControlRegAddrs                                      0x0404
