#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_UNIT_CLUSTER                    0x2

/* Hardware native debug stop type. 0: PC equals to reference PC. 1:          **
** Instruction count equals to reference instruction count. 2: Call depth is  **
** greater than reference call depth. 3: Call depth is less than reference    **
** call depth. 4: Call depth equals to reference call depth. 5: Call depth is **
** less than or equals to reference call depth. 6: PC equals reference PC and **
** Call depth equals to reference call depth. 7: PC equals reference PC or    **
** Call depth equals to reference call depth. 8: Write data to local storage  **
** address. 9: Read data from local storage address. 10: Write data to or     **
** read data from local storage address. 11: Write data to global address.    **
** 12: Read data from global storage address. 13: Write data to or read data  **
** from global storage address. 14: Immediately debug. 15: Kernel end.        */
#define GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE                              8:4
#define GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_End                            8
#define GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_Start                          4
#define GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_Type                         U05
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_EQ_PC                     0x00
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_EQ_INST_COUNT             0x01
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_GT_CALL_DEPTH             0x02
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_LT_CALL_DEPTH             0x03
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_EQ_CALL_DEPTH             0x04
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_LT_EQ_CALL_DEPTH          0x05
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_EQ_PC_AND_EQ_CALL_DEPTH   0x06
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_EQ_PC_OR_EQ_CALL_DEPTH    0x07
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_DATA_WRITE_AT_LOCAL_ADDRESS 0x08
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_DATA_READ_AT_LOCAL_ADDRESS 0x09
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_DATA_WRITE_OR_READ_AT_LOCAL_ADDRESS 0x0A
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_DATA_WRITE_AT_GLOBAL_ADDRESS 0x0B
#define   GCREG_HW_NATIVE_DEBUG_CONTROL_STOP_TYPE_DATA_READ_AT_GLOBAL_ADDRESS 0x0C
