#define   GCREG_HW_NATIVE_DEBUG_OPCODE_TYPE_READ_LOCAL_MEMORY               0x06
#define   GCREG_HW_NATIVE_DEBUG_OPCODE_TYPE_WRITE_GLOBAL_MEMORY             0x07
#define   GCREG_HW_NATIVE_DEBUG_OPCODE_TYPE_WRITE_LOCAL_MEMORY              0x08
#define   GCREG_HW_NATIVE_DEBUG_OPCODE_TYPE_READ_WORK_ATTRIBUTE0            0x09
#define   GCREG_HW_NATIVE_DEBUG_OPCODE_TYPE_READ_WORK_ATTRIBUTE1            0x0A
